function updateCellDOM(key, data) {
    if (!key || typeof key !== 'string' || key.length < 2) return;

    const colLetter = key[0].toUpperCase();
    const rowNum = parseInt(key.substring(1));

    const colIdx = COLUMNS.indexOf(colLetter);
    if (colIdx === -1 || isNaN(rowNum)) {
        console.error(`Invalid cell key format: ${key}`);
        return;
    }

    const element = getCellElement(colIdx, rowNum);

    if (element) {
        // 1. Update content
        element.textContent = data.value;

        // 2. Apply styles
        Object.keys(data.style).forEach(prop => {
            element.style[prop] = data.style[prop];
        });
    }
}
