function loadState() {
    const savedState = localStorage.getItem(STORAGE_KEY);
    if (savedState) {
        try {
            const loadedData = JSON.parse(savedState);
            // Merge loaded data into the initialized state, ensuring all keys exist
            spreadsheetData = { ...spreadsheetData, ...loadedData };

            // FIX: After loading state, we must update the DOM to reflect the saved values in every cell.
            Object.keys(spreadsheetData).forEach(key => {
                const value = spreadsheetData[key];
                if (value !== undefined && value !== null) {
                    updateCellDOM(key, value);
                }
            });

        } catch (e) {
            console.error("Error loading state:", e);
            // If corrupted, start fresh
            initializeState();
        }
    } else {
        initializeState();
    }
}
